import{c as t,Q as a,j as r,m as s}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"本文档组织结构","description":"","frontmatter":{},"headers":[{"level":1,"title":"本文档组织结构","slug":"本文档组织结构"}],"relativePath":"guide/编程指南/本文档组织结构.md","filePath":"guide/编程指南/本文档组织结构.md"}'),n={name:"guide/编程指南/本文档组织结构.md"};function l(o,e,i,_,d,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="本文档组织结构" tabindex="-1">本文档组织结构 <a class="header-anchor" href="#本文档组织结构" aria-label="Permalink to &quot;本文档组织结构&quot;">​</a></h1><p>本指南作为AscendC 算子开发综合性技术文档，详细阐述编程模型、语言扩展特性、C++类库API、硬件实现、以及调试调优等。无论是入门开发者还是资深工程师，均能通过本指南充分掌握如何高效释放昇腾AI处理器的完整计算潜能。</p><p>本文档的组织结构和各章内容如下：</p><ul><li><strong><a href="./编程模型/编程模型.html">编程模型</a></strong>：介绍Ascend C编程模型和编程范式。</li><li><strong><a href="./编译与运行/编译与运行.html">编译与运行</a></strong>：介绍如何编译Ascend C算子，以及算子运行需要的常用接口。</li><li><strong><a href="./语言扩展层/语言扩展层.html">语言扩展层</a></strong>：介绍语言扩展层特性，包括内置变量和函数、以及Ascend C扩展的C API。</li><li><strong><a href="./类库API/类库API.html">C++类库API</a></strong>：介绍Ascend C多层级类库API，包括单指令封装抽象的基础API、基于单核公共算法抽象的高阶API等。</li><li><strong><a href="./高级编程/硬件实现/硬件实现.html">硬件实现</a></strong>：介绍Ascend C硬件实现，包括昇腾AI处理器的硬件架构、硬件规格和使用约束。</li><li><strong><a href="./调试调优/调试调优.html">调试调优</a></strong>：介绍Ascend C算子如何进行功能调试和性能调优。</li></ul>',4)])])}const g=t(n,[["render",l]]);export{h as __pageData,g as default};
